// BST invariant: everything left < node < everything right, against INHERITED
// bounds. Comparing only against the parent is the classic wrong answer and
// it passes small tests.
func isValid(root *TreeNode, lo, hi *int) bool {
	if root == nil {
		return true
	}
	if lo != nil && root.Val <= *lo {
		return false
	}
	if hi != nil && root.Val >= *hi {
		return false
	}
	return isValid(root.Left, lo, &root.Val) && isValid(root.Right, &root.Val, hi)
}

func insert(root *TreeNode, v int) *TreeNode {
	if root == nil {
		return &TreeNode{Val: v}
	}
	if v < root.Val {
		root.Left = insert(root.Left, v)
	} else if v > root.Val {
		root.Right = insert(root.Right, v)
	}
	return root
}

// LCA in a BST: the first node that splits the two values.
func lca(root *TreeNode, p, q int) *TreeNode {
	for root != nil {
		switch {
		case p < root.Val && q < root.Val:
			root = root.Left
		case p > root.Val && q > root.Val:
			root = root.Right
		default:
			return root
		}
	}
	return nil
}
